# Generated by scripts/homebrew_formula.sh in bircni/git-statuses on every release.
# Changes made here are overwritten by the next release.
class GitStatuses < Formula
  desc "Display Git repository statuses in a table format"
  homepage "https://github.com/bircni/git-statuses"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/bircni/git-statuses/releases/download/1.0.0/git-statuses-1.0.0-aarch64-apple-darwin.tar.gz"
      sha256 "f647ac5741280bad094c613f0f07e06db56c873a5038ec206d907452b7760c4d"
    end
    on_intel do
      url "https://github.com/bircni/git-statuses/releases/download/1.0.0/git-statuses-1.0.0-x86_64-apple-darwin.tar.gz"
      sha256 "1417523141296c055836889291de28b38dba2739df7f3d93128337fa8506f999"
    end
  end

  on_linux do
    # Only an x86_64 build is published for Linux.
    depends_on arch: :x86_64

    on_intel do
      url "https://github.com/bircni/git-statuses/releases/download/1.0.0/git-statuses-1.0.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "bd82e6116ed80397942da47370fdd08b7d084bd805863c2970f423e1197237a2"
    end
  end

  def install
    bin.install "git-statuses"
    generate_completions_from_executable(bin/"git-statuses", "--completions")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/git-statuses --version")

    (testpath/"scan").mkpath
    assert_equal '{"failed":[],"repositories":[]}',
                 shell_output("#{bin}/git-statuses --json #{testpath}/scan").strip
  end
end
